function checker(role: 'host' | 'client'): (graph: any) => void {
  const api = builder as unknown as Record<string, any>
  const name = role === 'host' ? 'assertHostProductBuildGraph' : 'assertClientProductBuildGraph'
  expect(api[name], `${name} must enforce the Product graph`).toBeTypeOf('function')
  return api[name]
}

for (const [role, fixture] of [['host', hostFixture], ['client', clientFixture]] as const) {
  test(`${role} accepts exactly the complete reviewed Product graph`, () => checker(role)(fixture))
  test(`${role} rejects every missing or extra graph input and output contribution`, () => {
    const check = checker(role)
    for (const key of Object.keys(fixture.inputs)) {
      const missing: any = structuredClone(fixture); delete missing.inputs[key]
      expect(() => check(missing), key).toThrow()
      const contribution: any = structuredClone(fixture)
      delete Object.values(contribution.outputs as Record<string, any>)[0].inputs[key]
      expect(() => check(contribution), key).toThrow()
    }
    for (const key of ['node_modules/zod/surprise.js', 'packages/workbench/src/demo/DemoApp.tsx',
      'packages/workbench/src/client/probe/ProbeView.tsx', 'node_modules/@deepseek-ai/dsh-agent/index.js',
      'node_modules/crypto-browserify/index.js', 'packages/workbench/src/integration/harness-rc6/probe-host.ts']) {
      const extra: any = structuredClone(fixture); extra.inputs[key] = { bytes: 1, imports: [] }
      expect(() => check(extra), key).toThrow()
    }
  })
  test(`${role} rejects missing, duplicate, changed, or unreviewed import tuples`, () => {
    const check = checker(role)
    for (const [key, input] of Object.entries(fixture.inputs)) {
      for (let i = 0; i < input.imports.length; i++) {
        for (const operation of ['remove', 'duplicate', 'path', 'external', 'kind', 'attributes']) {
          const changed: any = structuredClone(fixture)
          const imports = changed.inputs[key].imports
          if (operation === 'remove') imports.splice(i, 1)
          if (operation === 'duplicate') imports.push(structuredClone(imports[i]))
          if (operation === 'path') imports[i].path = './unexpected.js'
          if (operation === 'external') imports[i].external = !imports[i].external
          if (operation === 'kind') imports[i].kind = 'dynamic-import'
          if (operation === 'attributes') imports[i].with = { type: 'json' }
          expect(() => check(changed), `${key} ${i} ${operation}`).toThrow()
        }
      }
    }
  })
  test(`${role} enforces single output, entrypoint, imports, exports and safe names`, () => {
    const check = checker(role)
    for (const mutate of [
      (g: any, o: any) => { g.outputs['extra.css'] = o },
      (_g: any, o: any) => { o.entryPoint = 'packages/workbench/src/demo/DemoApp.tsx' },
      (_g: any, o: any) => { o.cssBundle = 'extra.css' },
      (_g: any, o: any) => { o.imports.pop() },
      (_g: any, o: any) => { o.imports.push(o.imports[0]) },
      (_g: any, o: any) => { o.imports.push({ path: 'zod', kind: 'import-statement', external: true }) },
      (_g: any, o: any) => { o.imports[0].path = '@deepseek-ai/dsh-client-connection/private' },
      (_g: any, o: any) => { o.exports.push('unexpectedExport') },
      (_g: any, o: any) => { o.bytes = -0 },
      (g: any) => { g.inputs['../alias.ts'] = { bytes: 1, imports: [] } },
      (g: any) => { g.inputs['/absolute.ts'] = { bytes: 1, imports: [] } },
    ]) {
      const changed: any = structuredClone(fixture); mutate(changed, Object.values(changed.outputs)[0])
      expect(() => check(changed)).toThrow()
    }
  })
}

test('C34 preserves only the single input-only elided type import and forbids it at runtime', () => {
  const check = checker('host')
  const record = hostFixture.inputs['packages/workbench/src/application/project-service.ts']
  expect(record.imports.filter(i => i.path === './project-repository.js')).toEqual([
    { path: './project-repository.js', kind: 'import-statement', external: true },
  ])
  const changed: any = structuredClone(hostFixture)
  Object.values(changed.outputs as Record<string, any>)[0].imports.push(record.imports[1])
  expect(() => check(changed)).toThrow()
})

test('real Product build is exact, preserves C8, and normalizes graph hashes across allowed outdirs', async () => {
  await mkdir(path.join(root, '.tmp'), { recursive: true })
  const temp = await mkdtemp(path.join(root, '.tmp', 'product-build-'))
  try {
    const first: any = await builder.buildWorkbench({ outdir: path.join(temp, 'one') })
    const second: any = await builder.buildWorkbench({ outdir: path.join(temp, 'two') })
    for (const [role, fixture] of [['host', hostFixture], ['client', clientFixture]] as const) {
      const meta = first[`${role}Metafile`]
      expect(Object.keys(meta.inputs).sort()).toEqual(Object.keys(fixture.inputs).sort())
      expect(first.graphHashes[role]).toBe(second.graphHashes[role])
      expect(first.graphHashes[role]).toMatch(/^[0-9a-f]{64}$/)
      expect(JSON.stringify(first.graphs[role])).not.toContain(temp)
    }
    const host = await readFile(path.join(temp, 'one/index.js'), 'utf8')
    const client = await readFile(path.join(temp, 'one/client.js'), 'utf8')
    expect(host + client).toContain('/dsh-pm-workbench-product-v1')
    expect(host + client).not.toMatch(/\/dsh-pm-workbench-v1|counter\.increment|pm-workbench-probe|storage-gate/)
    expect(client).not.toMatch(/\bBuffer\b|node:crypto|crypto-browserify|dsh-storage-domain/)
    expect(host).not.toContain('pm-workbench-product-launcher')
    expect(client).toContain("window.__ModuleLoader__.load({ id:'@knight/dsh-pm-workbench'")
    expect(host).toContain('internal')
    for (const [file, bytes] of [['lib/index.js', host], ['lib/client.js', client]]) {
      expect(first.outputHashes[file!]).toBe(createHash('sha256').update(bytes!).digest('hex'))
    }
  } finally { await rm(temp, { recursive: true, force: true }) }
})
